=1;st.leftPage=1 notice('Added '..name..' to '..weapon..'. Select Save & Apply to test; use Default to undo.') end local function parseCatalogues() if not belongs() then notice('Join RIVALS first'); return end local new={skins={},wraps={},finishers={},charms={}} local count=0 local fullSources={} for _,url in ipairs({SITE..'full_catalog.json', CATALOG_RAW..'full_catalog.json'}) do local data=json(fetch(url)) if type(data)=='table' then fullSources[#fullSources+1]=data end end local skinSeenByWeapon={} local previews={} for _,full in ipairs(fullSources) do if type(full)=='table' then for _,item in ipairs(full) do if type(item)=='table' and type(item.name)=='string' and type(item.skins)=='table' then local arr=new.skins[item.name] or {}; local seen=skinSeenByWeapon[item.name] or {} for _,skin in ipairs(item.skins) do if type(skin)=='string' and skin~='Standard' and skin~='Default' and not seen[skin] then arr[#arr+1]=skin; seen[skin]=true end end table.sort(arr) new.skins[item.name]=arr skinSeenByWeapon[item.name]=seen end end end end for _,url in ipairs({SITE..'skin_icon_map.json', CATALOG_RAW..'skin_icon_map.json'}) do local map=json(fetch(url)) if type(map)=='table' then for weapon,skins in pairs(map) do if type(weapon)=='string' and linkedWeapon(weapon) and type(skins)=='table' then local arr=new.skins[weapon] or {} local seen=skinSeenByWeapon[weapon] or {} for name,detail in pairs(skins) do if type(name)=='string' and type(detail)=='table' and type(detail.src)=='string' and detail.src:match('^assets/images/[%w_%-]+%.png$') then previews[weapon]=previews[weapon] or {} previews[weapon][name]={url=SITE..detail.src, rarity=tostring(detail.rarity or '')} end if type(name)=='string' and name~='Default' and name~='Standard' and not seen[name] then arr[#arr+1]=name;seen[name]=true end end new.skins[weapon]=arr skinSeenByWeapon[weapon]=seen end end end end for _,arr in pairs(new.skins) do table.sort(arr); count=count+#arr end local wrapData=extract(fetch(SITE..'assets/wraps.js'),'WRAPS') for _,item in ipairs(type(wrapData)=='table' and wrapData or {}) do if type(item)=='table' and type(item[1])=='string' and not item[1]:find('MISSING_',1,true) then new.wraps[#new.wraps+1]=item[1] end end local cosmeticsJs=fetch(SITE..'assets/cosmetics.js') for _,entry in ipairs({{'finishers','FINISHERS'},{'charms','CHARMS'}}) do local data=extract(cosmeticsJs,entry[2]) for _,item in ipairs(type(data)=='table' and data or {}) do if type(item)=='table' and type(item[1])=='string' and not item[1]:find('MISSING_',1,true) then new[entry[1]][#new[entry[1]]+1]=item[1] end end end for _,key in ipairs({'wraps','finishers','charms'}) do table.sort(new[key],function(a,b) return a:lower()<b:lower() end) end if next(previews) then st.previewMap=previews;st.previewKey=nil;st.previewData=nil end if count>10 then st.catalogue.skins=new.skins end for _,key in ipairs({'wraps','finishers','charms'}) do if #new[key]>0 then st.catalogue[key]=new[key] end end st.catalogState=('Lists: %d skins, %d wraps, %d finishers, %d charms'):format(count,#st.catalogue.wraps,#st.catalogue.finishers,#st.catalogue.charms) notice(st.catalogState)
