end local function sourceList() if st.mode=='avatar' then return {} end if st.mode=='skins' or st.mode=='newskins' then return categories[st.slot] or {} end if st.mode=='wraps' or st.mode=='finishers' or st.mode=='charms' then return sortedNames(st.mode) end if st.mode=='sounds' then return {'Hit','Critical','Kill'} end if st.mode=='spoof' then return {'Level','Streak','ELO'} end return {'Preset'} end local function targetList() local result={{name='Original / Default',value=false}} local names={} if st.mode=='skins' then names=st.catalogue.skins[st.source] or offline[st.source] or {} elseif st.mode=='newskins' then names=st.unlinked elseif st.mode=='wraps' or st.mode=='finishers' or st.mode=='charms' then names=st.catalogue[st.mode] or {} elseif st.mode=='skybox' then names=sky elseif st.mode=='lighting' then return light elseif st.mode=='sounds' then return sound elseif st.mode=='spoof' then for _,n in ipairs(profilePresets[st.source] or {}) do result[#result+1]={name=tostring(st.source)..' '..tostring(n), value=tostring(n)} end if st.value and not (function() for _,v in ipairs(profilePresets[st.source] or {}) do if tostring(v)==tostring(st.value) then return true end end return false end)() then table.insert(result,2,{name='Saved '..tostring(st.value),value=st.value}) end return result end local found={} for _,name in ipairs(names) do if name~=st.source and not found[name] then result[#result+1]={name=name,value=name};found[name]=true end end if st.value and not found[st.value] then table.insert(result,2,{name='Keep existing: '..st.value,value=st.value}) end return result end local function existsInTarget(value) if value==nil or value==false then return true end for _,x in ipairs(targetList()) do local v=x.value~=nil and x.value or x[2] if v==value then return true end end return false end local function conflicted(section,key,value,raw) if not value or value==false then return nil end if section~='skins' and section~='finishers' and section~='charms' then return nil end local values=sectionValues(raw,section) for k,v in pairs(values) do if k~=key and (v==value or k==value) then return ('%s already uses %s. Reset that choice first.'):format(k,value) end end return nil end local function safeWrite(new) local old=read(CONF) if type(old)~='string' or old~=st.config then return false,'Other changer updated the file. RELOAD settings first.' end if new==old then return true,'No changes needed' end if type(writefile)~='function' then return false,'Matcha file writing is unavailable' end local backed=pcall(function() writefile(BACK,old) end) if not backed or read(BACK)~=old then return false,'Backup failed, original left unchanged' end local undoOk=pcall(function() writefile(UNDO_FILE,old) end) if not undoOk or read(UNDO_FILE)~=old then return false,'Undo checkpoint failed; config unchanged' end local wrote=pcall(function() writefile(CONF,new) end) if not wrote or read(CONF)~=new then pcall(function() writefile(CONF,old) end) return false,'Config verification failed. Rollback attempted.' end st.config=new;return true,'Selection saved to config' end
commitCosmeticChoice=function(section,item,look)
 local changed=patch(st.config,section,{[item]=look})
