function Q.saveQueueBatch() if st.engineBusy then notice('Wait for Apply to finish.');return false end if not st.config or read(CONF)~=st.config then notice('External config changed. Reload before applying.');return false end local entries=Q.queuedItems() if #entries==0 then notice('Nothing new to save; existing cosmetics are still saved.');return true end local newer=st.config for _,e in ipairs(entries) do if not QUEUE_MODES[e.section] or not Q.safeQueuedName(e.item) or (e.look~=false and not Q.safeQueuedName(e.look)) then notice('Invalid queued entry; no changes made.');return false end local changes={[e.item]=e.look} if e.section=='skybox' then for _,key in ipairs({'All','BK','DN','FT','LF','RT','UP'}) do changes[key]=false end end newer=patch(newer,e.section,changes) end for _,e in ipairs(entries) do local err=conflicted(e.section,e.item,e.look,newer) if err then notice('Batch not saved: '..err);return false end end local ok,msg=safeWrite(newer) if not ok then notice('Batch not saved: '..msg);return false end for _,e in ipairs(entries) do if e.look~=false then recordRecent(e.section,e.item,tostring(e.look)) end end local clearOk,clearErr=Q.persistQueue({}) if not clearOk then notice('Saved config, but queued file not cleared: '..clearErr) else notice('Saved '..#entries..' cosmetic picks together. Rejoin or Apply All to see them.') end st.dirty=false return true end local function save() if QUEUE_MODES[st.mode] then return Q.saveQueueBatch() end if st.mode=='tracers' or st.mode=='avatar' or st.mode=='newskins' or st.mode=='finder' or st.mode=='favorites' or st.mode=='presets' then notice('Choose an appearance first.'); return false end if st.mode=='spoof' then local candidate=tostring(st.profileDraft or '') if candidate=='' then st.value=nil elseif candidate:match('^%d+$') and #candidate<=9 then st.value=tostring(tonumber(candidate) or 0) else notice('Enter a whole number (up to 9 digits)'); return false end end if st.engineBusy then notice('Wait until Apply completes'); return false end if not belongs() then notice('Only works in RIVALS'); return false end if not st.config then notice('Use Reload settings first'); return false end if not st.source then notice('Choose an item first');return false end if not existsInTarget(st.value) then notice('This appearance is unavailable in the current list');return false end local target=st.value or false if st.mode=='spoof' then local n=target and tonumber(target) if target~=false and (not n or n<0 or n>999999999 or n~=math.floor(n)) then notice('Use a whole number from 0 to 999999999.'); return false end end if tostring(st.source):find('[\r\n=]') or (target~=false and tostring(target):find('[\r\n]')) then notice('Invalid cosmetic name; config not changed'); return false end local err=conflicted(st.mode,st.source,target,st.config) if err then notice(err);return false end local updates={[st.source]=target} if st.mode=='skybox' then for _,key in ipairs({'All','BK','DN','FT','LF','RT','UP'}) do updates[key]=false end end local newer=patch(st.config,st.mode,updates) local ok,msg=safeWrite(newer) if ok then st.dirty=false if target~=false then recordRecent(st.mode,st.source,tostring(target)) end end if ok and st.mode=='spoof' then profileLiveCheck() end notice(msg) return ok end local function engineSource() for _,path in ipairs(ENGINES) do if fileExists(path) then local content=read(path) if type(content)=='string' and #content>1000 then return path,content end end end return nil,nil end local function launchEngine(applyingProfile)
 if st.engineBusy then notice('Changer is already running');return end
 local time=protected(function() return tick() end) or 0
