t) if not ok or read(path)~=snapshot then if old then pcall(writefile,path,old) end notice('Preset save failed verification');return false end st.presetConfirm=nil notice('Saved cosmetic preset '..slot..' (profile settings untouched).') return true end local function loadPreset(slot,doApply) if st.engineBusy then notice('Wait for Apply first');return false end local snap=read(presetPath(slot)) if not presetValid(snap) then notice('Preset '..slot..' is empty');return false end if not st.config or read(CONF)~=st.config then notice('Config changed. Reload settings first.');return false end local newer=st.config for _,section in ipairs(PRESET_SECTIONS) do local updates={} for key in pairs(sectionValues(newer,section)) do updates[key]=false end for key,value in pairs(sectionValues(snap,section)) do updates[key]=value end newer=patch(newer,section,updates) end local ok,msg=safeWrite(newer) if not ok then notice('Preset not loaded: '..msg);return false end st.presetConfirm=nil; st.dirty=false notice('Loaded preset '..slot..' safely. Local profile was preserved.') if doApply then launchEngine(false) end return true end function V14.undoLastChange(doApply) if st.engineBusy then notice('Wait for Apply to finish.');return false end if not st.config or read(CONF)~=st.config then notice('Config changed externally; reload first.');return false end local snap=read(UNDO_FILE) if type(snap)~='string' or snap=='' or snap==st.config then notice('No previous PRISM change to undo.');return false end local before=st.config local ok,msg=safeWrite(snap) if not ok then notice('Undo failed: '..msg);return false end st.dirty=false;st.undoConfirm=false notice('Previous PRISM config restored. Cosmetic changes may need re-equip.') if doApply then launchEngine(false) end return true end function V14.captureOriginal() if not st.config or read(CONF)~=st.config then notice('Reload external config changes first.');return false end local prior=read(RESTORE_FILE) if type(prior)=='string' and presetVali